    int codigo() const noexcept { return codigo_; }
    void escribir(std::ostream& salida) const;
private:
    int codigo_;
};

void MedidaIdentificada::escribir(std::ostream& salida) const {
    // Conserva el informe de la base y agrega el codigo propio.
    Medida::escribir(salida);
}

void mostrar_base(const Medida& dato, std::ostream& salida) {
    // Escribe el informe disponible por el acceso constante a Medida.
    (void)dato;
    (void)salida;
}

