    dato.escribir(despues);
    mostrar_base(dato, base_despues);
    std::cout << "TrasCambio:" << despues.str() << '\n'
              << "BaseTrasCambio:" << base_despues.str() << '\n'
              << "Estado:(" << dato.numero() << ',' << dato.codigo() << ')';
    return 0;
}

